#Requires -Version 5.1
# feat-rrhh-asignaciones-pdf.ps1
# 1. ANCHURA: modal cambiado de size="lg" (max-w-2xl) a size="xl" (max-w-4xl)
#    Estado con whitespace-nowrap para que "3-En ejecucion" no parta en 2 lineas.
# 2. FILTROS: fecha desde/hasta, obra, estado (texto libre) sobre las asignaciones.
#    Se resetean al abrir otra ficha.
# 3. PDF: boton "Generar PDF" en la pestaña Asignaciones.
#    - jsPDF + jspdf-autotable (ya instalados en el proyecto)
#    - A4 horizontal, cabecera con logo LOGO_BASE64, nombre, perfil, fecha
#    - Tabla: Inicio | Fin | Obra | Estado
#    - Periodo consultado si hay filtros de fecha
#    - Numeracion de paginas: Pagina X de Y
#    - Nombre archivo: asignaciones_Nombre_DD-MM-AAAA.pdf
#    - Import dinamico para evitar SSR y conflictos de bundle
# 4. PERMISOS: solo usuarios con permiso ver RRHH pueden abrir la ficha
#    y por tanto ver el PDF.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> feat: asignaciones filtros + PDF" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains('size="xl"'))              { Write-Host "  OK: modal size xl (mas ancho)" -ForegroundColor Green } else { Write-Host "  ERROR size" -ForegroundColor Red }
if ($c.Contains("whitespace-nowrap"))      { Write-Host "  OK: whitespace-nowrap en Estado" -ForegroundColor Green } else { Write-Host "  ERROR nowrap" -ForegroundColor Red }
if ($c.Contains("filtroDesde"))            { Write-Host "  OK: filtros fecha/obra/estado" -ForegroundColor Green } else { Write-Host "  ERROR filtros" -ForegroundColor Red }
if ($c.Contains("generatePdfAsignaciones")) { Write-Host "  OK: generacion PDF" -ForegroundColor Green } else { Write-Host "  ERROR pdf" -ForegroundColor Red }
if ($c.Contains("jspdf-autotable"))        { Write-Host "  OK: jspdf-autotable" -ForegroundColor Green } else { Write-Host "  ERROR autotable" -ForegroundColor Red }

Write-Host ""
Write-Host "  git add src\app\maestros\recursos-humanos\page.tsx"
Write-Host '  git commit -m "feat: RRHH asignaciones - modal xl + whitespace-nowrap + filtros + PDF"'
Write-Host "  git push"
